item.aggregated_output:
:root {
  font-family: "Manrope Variable", sans-serif;
  color: #f0edf3;
  background: #000;
  color-scheme: dark;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --surface: #111;
  --text: #f0edf3;
  --muted: #ada6b4;
  --accent: #b67be5;
  --line: #28232e;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  min-width: 320px;
}
button,
input {
  font: inherit;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
button {
  cursor: pointer;
}
a {
  color: inherit;
}
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 5px;
}
::selection {
  color: #fff;
  background: #5c277f;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.skip-link {
  position: absolute;
  left: 24px;
  top: 16px;
  transform: translateY(-180%);
  padding: 12px 16px;
  background: var(--surface);
  z-index: 2;
}
.skip-link:focus {
  transform: none;
}
.app-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: 0 auto;
  padding: 0 64px;
  display: flex;
  flex-direction: column;
}
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 32px 0;
  border-bottom: 1px solid #1c1920;
}
.wordmark {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  font-size: 29px;
  line-height: 1.1;
  font-weight: 750;
  letter-spacing: -1.7px;
  text-decoration: none;
}
.header-context {
  color: var(--muted);
  font-size: 13px;
}
main {
  width: min(100%, 800px);
  margin: 74px auto 48px;
  flex: 1;
}
.search-intro {
  margin-bottom: 30px;
}
h1 {
  font-size: clamp(28px, 3.1vw, 38px);
  line-height: 1.2;
  letter-spacing: -1.4px;
  font-weight: 600;
  margin: 0 0 13px;
}
.search-intro p {
  color: var(--muted);
  font-size: 15px;
  line-height: 1.7;
  margin: 0;
}
.search-field {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 22px;
  min-height: 74px;
  border: 1px solid #493553;
  border-radius: 10px;
  background: var(--surface);
  transition:
    border-color 120ms ease,
    box-shadow 120ms ease;
}
.search-field:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px #a863d61c;
}
.search-icon {
  display: flex;
  color: var(--accent);
  flex: none;
}
.search-field input {
  appearance: none;
  background: transparent;
  color: var(--text);
  border: 0;
  outline: none;
  min-width: 0;
  width: 100%;
  padding: 21px 0;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.6;
  caret-color: var(--accent);
}
.search-field input::-webkit-search-cancel-button {
  display: none;
}
.search-field input::placeholder {
  color: #9c929f;
  font-weight: 400;
}
.search-shortcut {
  flex: none;
  white-space: nowrap;
  font: inherit;
  font-size: 14px;
  color: var(--muted);
  border: 1px solid #453c4a;
  border-radius: 5px;
  min-width: 26px;
  padding: 2px 7px;
  text-align: center;
}
.clear-button {
  color: var(--muted);
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  flex: none;
  border: 0;
  border-radius: 5px;
  background: transparent;
}
.clear-button:hover {
  color: var(--text);
  background: #2a2130;
}
.search-help {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
  min-height: 20px;
  margin: 12px 2px 0;
}
.results-region {
  margin-top: 30px;
  min-height: 342px;
}
.results-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  min-height: 28px;
  padding-bottom: 16px;
}
.results-heading h2 {
  color: var(--text);
  font-size: 13px;
  line-height: 1.5;
  font-weight: 500;
  margin: 0;
}
.results-heading > span {
  color: var(--muted);
  font-size: 12px;
}
.results-list,
.loading-rows {
  border-top: 1px solid var(--line);
}
.results-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.entity-row {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 21px 0;
  border-bottom: 1px solid var(--line);
}
.entity-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  color: var(--accent);
  border: 1px solid #483159;
  border-radius: 8px;
  background: #25182f;
}
.entity-name {
  font-size: 17px;
  line-height: 1.6;
  font-weight: 500;
  overflow-wrap: anywhere;
}
.entity-kind {
  display: inline-flex;
  align-items: center;
  justify-self: end;
  gap: 6px;
  max-width: 210px;
  padding: 4px 8px;
  border: 1px solid #483159;
  border-radius: 6px;
  background: #25182f;
  color: #d3b1ef;
  font-size: 12px;
  line-height: 1.5;
}
.entity-kind svg {
  flex: none;
  color: var(--accent);
}
.entity-kind-label {
  min-width: 0;
  overflow-wrap: anywhere;
}
mark {
  background: none;
  color: #cc9bf1;
  font-weight: 650;
}
/* Shape distinguishes roles; shared colour gives both equal emphasis. */
.entity-indicator {
  position: relative;
  justify-self: start;
}
.entity-tooltip {
  position: absolute;
  z-index: 1;
  top: 100%;
  left: 0;
  padding-top: 6px;
  width: max-content;
  max-width: min(280px, calc(100vw - 48px));
  pointer-events: auto;
}
.entity-tooltip > span {
  display: block;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: #19141f;
  color: var(--text);
  font-size: 12px;
  line-height: 1.5;
  overflow-wrap: anywhere;
  box-shadow: 0 4px 16px #0008;
}
.entity-legend {
  display: flex;
  align-items: center;
  gap: 18px;
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 11px;
}
.entity-legend > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.entity-legend svg {
  color: var(--accent);
}
.results-note {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
  margin: 20px 0 0;
}
.starting-state,
.message-state {
  display: flex;
  align-items: center;
  flex-direction: column;
  text-align: center;
  padding: 48px 12px 44px;
}
.start-symbol,
.state-icon {
  display: grid;
  place-items: center;
  color: #9e83b5;
  width: 52px;
  height: 52px;
  background: #151019;
  border: 1px solid #302137;
  border-radius: 14px;
  margin-bottom: 20px;
}
.starting-state h2,
.message-state h2 {
  font-size: 16px;
  line-height: 1.5;
  font-weight: 500;
  margin: 0 0 9px;
  max-width: 100%;
  overflow-wrap: anywhere;
}
.starting-state p,
.message-state p {
  font-size: 13px;
  line-height: 1.7;
  margin: 0;
  color: var(--muted);
  max-width: 440px;
}
.examples {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 10px;
  margin-top: 24px;
  font-size: 12px;
  color: var(--muted);
}
.examples > span {
  margin-right: 3px;
}
.examples button {
  padding: 6px 12px;
  border: 1px solid #403149;
  background: #151019;
  color: #d2b0ed;
  border-radius: 5px;
  font-size: 12px;
}
.examples button:hover {
  background: #25182f;
  border-color: #785192;
}
.retry-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 24px;
  padding: 10px 16px;
  font-size: 13px;
  border: 1px solid #75508f;
  border-radius: 6px;
  color: #ebd4fc;
  background: #301b41;
}
.retry-button:hover {
  background: #432355;
}
.text-button {
  margin-top: 22px;
  color: #cc9bf1;
  font-size: 13px;
  padding: 4px 0;
  border: 0;
  background: none;
  text-decoration: underline;
  text-underline-offset: 4px;
}
.loading-indicator {
  width: 14px;
  height: 14px;
  border: 2px solid #33203f;
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 900ms linear infinite;
}
.loading-row {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 21px 0;
  border-bottom: 1px solid var(--line);
}
.skeleton-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  flex: none;
  background: #151119;
}
.skeleton-name {
  max-width: 350px;
  height: 13px;
  border-radius: 3px;
  background: #1c1622;
}
.app-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  border-top: 1px solid #1c1920;
  padding: 24px 0;
  color: #9d93a5;
  font-size: 11px;
  line-height: 1.7;
}
.app-footer a {
  text-decoration: none;
}
.app-footer a:hover {
  color: #dfc7f0;
  text-decoration: underline;
  text-underline-offset: 4px;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}
@media (max-width: 700px) {
  .app-shell {
    padding: 0 24px;
  }
  .app-header {
    padding: 25px 0;
  }
  main {
    margin-top: 52px;
  }
  .search-intro p {
    font-size: 14px;
  }
  .search-field {
    min-height: 66px;
    padding: 0 16px;
    gap: 12px;
  }
  .search-field input {
    font-size: 16px;
    padding: 18px 0;
  }
  .entity-row {
    gap: 12px;
  }
  .entity-name {
    font-size: 15px;
  }
}
@media (max-width: 480px) {
  .app-shell {
    padding: 0 20px;
  }
  .wordmark {
    font-size: 26px;
  }
  .header-context {
    font-size: 11px;
  }
  h1 {
    font-size: 28px;
    letter-spacing: -1px;
  }
  .search-shortcut {
    display: none;
  }
  .entity-row {
    grid-template-columns: 32px minmax(0, 1fr);
    gap: 5px 12px;
    padding: 18px 0;
  }
  .entity-icon {
    width: 32px;
    height: 32px;
  }
  .entity-kind {
    grid-column: 2;
    justify-self: start;
    max-width: 100%;
  }
  .results-heading {
    gap: 12px;
  }
  .results-heading > span {
    font-size: 11px;
  }
  .app-footer {
    font-size: 11px;
  }
}

.entity-name {
  text-decoration: none;
}
.entity-name:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.detail-page {
  width: min(100%, 1000px);
  margin-top: 40px;
}
.funder-page {
  --accent: #64cfb5;
}
.back-link {
  display: inline-block;
  margin-bottom: 40px;
  font-size: 13px;
  color: var(--muted);
  text-underline-offset: 4px;
}
.profile-heading {
  padding-bottom: 30px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 34px;
}
.profile-type {
  display: inline-flex;
  gap: 10px;
  align-items: center;
  color: var(--accent);
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 18px;
}
.profile-heading h1 {
  font-size: clamp(30px, 4vw, 48px);
  overflow-wrap: anywhere;
  max-width: 850px;
}
.profile-meta {
  color: var(--accent);
  font-size: 17px;
  margin: 12px 0 24px;
}
.profile-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 20px 48px;
  margin: 0;
  font-size: 14px;
  line-height: 1.7;
}
.profile-facts dt {
  color: var(--muted);
  font-size: 12px;
}
.profile-facts dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.detail-page h2 {
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.5px;
  margin: 0 0 12px;
}
.detail-section-heading p,
.summary-context,
.coverage-note,
.detail-footnote,
.empty-details {
  font-size: 14px;
  line-height: 1.8;
  color: var(--muted);
  max-width: 78ch;
}
.declarations-list,
.funding-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.declarations-list {
  margin-top: 28px;
}
.declaration {
  border-top: 1px solid var(--line);
  padding: 24px 0 30px;
}
.declaration-heading {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 24px;
}
.declaration-heading h3 {
  margin: 0 0 6px;
  font-size: 17px;
  font-weight: 600;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.declaration-heading p,
.declaration-reference,
.payment-type,
.currency-label,
.empty-entry {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}
.declaration-heading p {
  flex-shrink: 0;
  padding-top: 3px;
}
.funding-list {
  margin-top: 20px;
}
.funding-list li {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 24px;
  padding: 14px 18px;
  background: var(--surface);
  border-bottom: 1px solid #222;
}
.funding-source {
  min-width: 0;
  font-size: 14px;
  line-height: 1.7;
  overflow-wrap: anywhere;
}
.funding-source a,
.summary-columns a {
  text-decoration-color: #695476;
  text-underline-offset: 4px;
}
.funder-page .summary-columns a {
  text-decoration-color: #437c6e;
}
.funding-source span,
.funding-value span {
  display: block;
}
.funding-value {
  text-align: right;
  max-width: 50%;
  flex-shrink: 0;
}
.amount {
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  overflow-wrap: anywhere;
}
.empty-entry {
  margin-top: 16px;
}
.recorded-names {
  margin-bottom: 30px;
}
.recorded-names ul {
  margin: 0;
  padding-left: 20px;
  font-size: 14px;
  line-height: 1.8;
}
.recorded-names li {
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}
.summary-context {
  margin: 0 0 24px;
}
.coverage-note {
  border-left: 2px solid var(--accent);
  padding: 10px 16px;
  background: var(--surface);
  margin: 0 0 30px;
}
.currency-section {
  border-top: 1px solid var(--line);
  padding-top: 26px;
  margin-top: 32px;
}
.currency-section > h2 {
  color: var(--accent);
}
.summary-columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 48px;
}
.summary-columns h3 {
  font-size: 16px;
  font-weight: 600;
  margin: 14px 0 12px;
}
.summary-columns table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  font-size: 14px;
  line-height: 1.6;
}
.summary-columns th,
.summary-columns td {
  text-align: left;
  vertical-align: top;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
  overflow-wrap: anywhere;
}
.summary-columns thead th {
  font-size: 12px;
  font-weight: 400;
  color: var(--muted);
  padding-top: 0;
}
.summary-columns th {
  font-weight: 500;
  padding-right: 16px;
  width: 54%;
}
.summary-columns td,
.summary-columns th:last-child {
  text-align: right;
}
.entry-count,
.partial-note {
  display: block;
  font-size: 11px;
  font-weight: 400;
  line-height: 1.7;
  color: var(--muted);
  margin-top: 4px;
}
.ranking-note {
  margin: 0 0 12px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}
.detail-footnote {
  margin-top: 32px;
  font-size: 12px;
}
.detail-message {
  padding: 32px 0 80px;
}
.detail-message p {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.8;
}
.detail-message .loading-indicator {
  display: block;
  margin-bottom: 24px;
}
.empty-details {
  padding: 24px 0;
}
@media (max-width: 700px) {
  .summary-columns {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .declaration-heading {
    flex-direction: column;
    gap: 8px;
  }
  .back-link {
    margin-bottom: 32px;
  }
  .funding-list li {
    padding: 14px 12px;
    gap: 14px;
  }
}

.entity-text {
  min-width: 0;
}
.entity-alias {
  display: block;
  margin-top: 0.25rem;
  color: var(--muted);
  font-size: 0.85rem;
  overflow-wrap: anywhere;
}

.member-identity {
  margin: 0 0 28px;
  border-bottom: 1px solid var(--line);
}
.member-identity-title {
  display: flex;
  align-items: center;
  gap: 18px;
}
.member-identity h1 {
  margin: 0;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  line-height: 1.15;
  overflow-wrap: anywhere;
}
.member-identity-info > p {
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin: 12px 0 16px;
}
.member-identity-info > p span {
  border-left: 1px solid var(--line);
  padding-left: 24px;
}
.member-tabs {
  display: flex;
  gap: 28px;
}
.member-tabs a {
  padding: 12px 0;
  color: var(--muted);
  text-decoration: none;
  border-bottom: 3px solid transparent;
}
.member-tabs a[aria-current="page"] {
  color: var(--text);
  border-color: var(--accent);
}
.member-breakdown {
  min-width: 0;
}
.member-total {
  margin: 0;
  font-size: clamp(1.8rem, 3.2vw, 2.7rem);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.filter-context,
.history-result-count {
  color: var(--muted);
  font-size: 0.85rem;
  line-height: 1.6;
}
.category-list {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 20px;
}
.category-label {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 10px;
}
.category-label > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.category-label .amount {
  text-align: right;
}
.signed-bar {
  position: relative;
  height: 9px;
  background: var(--surface);
}
.signed-bar::after {
  content: "";
  position: absolute;
  left: var(--baseline);
  top: -3px;
  bottom: -3px;
  width: 1px;
  background: var(--muted);
}
.signed-bar > span {
  position: absolute;
  left: var(--baseline);
  height: 100%;
  background: var(--accent);
}
.signed-bar > span.negative {
  left: auto;
  right: calc(100% - var(--baseline));
  opacity: 0.65;
}
.history-link {
  display: inline-block;
  margin-top: 24px;
}
.history-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: end;
  margin: 24px 0 12px;
}
.history-filters label {
  display: grid;
  gap: 8px;
  font-size: 0.9rem;
}
.history-filters input {
  color-scheme: dark;
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 6px;
  font: inherit;
  padding: 10px 12px;
}
.history-filters button {
  padding: 11px 16px;
}
.history-pagination {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  margin-top: 28px;
}
.history-pagination button {
  min-width: 90px;
  padding: 10px 16px;
}
button:disabled {
  opacity: 0.4;
  cursor: default;
}
@media (max-width: 600px) {
  .member-identity-title {
    align-items: flex-start;
    gap: 12px;
  }
  .member-identity .profile-type {
    margin-top: 7px;
  }
  .member-identity-info > p {
